python3 - <<'PY'
import urllib.request
for url in ['https://en.wikipedia.org/wiki/Ferrierite','https://en.wikipedia.org/wiki/Gaultite']:
    print('URL',url)
    try:
        data=urllib.request.urlopen(url,timeout=10).read(200000).decode('utf-8','ignore')
        for term in ['density','named','Canadian','rare','specific gravity','lowest','smallest']:
            idx=data.lower().find(term)
            if idx!=-1:
                print(term, data[max(0,idx-200):idx+400].replace('\n',' ')[:800])
        print('len',len(data))
    except Exception as e:
        print('ERR',e)
PY
